mapper.update:
	/* 구독 업데이트(재구독) */
    UPDATE 
    	push_subscription
    SET 
    	is_active = 1, p256dh = #{p256dh}, auth = #{auth}
    WHERE 
    	endpoint = #{endpoint} AND mbr_cd = #{mbrCd}

	/* 회원 코드로 알림 스케줄(JSON) 업데이트 */
    UPDATE
        push_subscription
    SET
        notification_schedule = #{notificationScheduleJson}
    WHERE
        mbr_cd = #{mbrCd}
